CREATE OR REPLACE FUNCTION public.save_weekly_reply_draft(p_id uuid,p_letter uuid,p_reply uuid,p_content text) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE rid uuid; BEGIN IF NOT public.campaign_access_active() THEN RAISE EXCEPTION 'Jogador não autorizado'; END IF; SELECT id INTO rid FROM public.letter_replies WHERE id=p_id OR (author_user_id=auth.uid() AND idempotency_key=p_id); IF FOUND THEN UPDATE public.letter_replies SET content=p_content WHERE id=rid AND author_user_id=auth.uid() AND publication_state='draft'; IF NOT FOUND THEN RAISE EXCEPTION 'Rascunho indisponível'; END IF; RETURN rid; END IF; RETURN public.reply_weekly_message(p_letter,p_reply,p_content,p_id,true); END $$;
CREATE OR REPLACE FUNCTION public.schedule_weekly_reply_draft(p_id uuid) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE r public.letter_replies;n integer;target integer; BEGIN IF NOT public.campaign_access_active() THEN RAISE EXCEPTION 'Jogador não autorizado'; END IF; SELECT * INTO r FROM public.letter_replies WHERE id=p_id AND author_user_id=auth.uid() FOR UPDATE; IF NOT FOUND THEN RAISE EXCEPTION 'Rascunho indisponível'; END IF; IF r.publication_state<>'draft' THEN RETURN; END IF; n:=public.open_letter_round(); IF n IS NULL AND NOT public.is_campaign_admin() THEN RAISE EXCEPTION 'Missivas fechadas, aguarde o narrador abrir a próxima semana'; END IF; n:=coalesce(n,(SELECT coalesce(max(number),0) FROM public.letter_rounds)); target:=CASE WHEN public.is_campaign_admin() OR NOT EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=r.recipient_user_id AND role='admin') THEN n+1 ELSE n END; IF btrim(r.content)='' THEN RAISE EXCEPTION 'Escreva a resposta'; END IF; UPDATE public.letter_replies SET creation_week=n,delivery_week=target,publication_state=CASE WHEN target=public.open_letter_round() THEN 'delivered' ELSE 'scheduled' END,delivered_at=CASE WHEN target=public.open_letter_round() THEN now() END WHERE id=r.id; INSERT INTO public.sync_outbox(entity_type,entity_id,version,payload) SELECT 'reply',id,1,to_jsonb(t) FROM public.letter_replies t WHERE id=r.id ON CONFLICT DO NOTHING; UPDATE public.sync_outbox SET state='pending',next_attempt_at=now() WHERE entity_id=r.id; END $$;
REVOKE ALL ON FUNCTION public.save_weekly_reply_draft(uuid,uuid,uuid,text),public.schedule_weekly_reply_draft(uuid) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.save_weekly_reply_draft(uuid,uuid,uuid,text),public.schedule_weekly_reply_draft(uuid) TO authenticated;